/* eslint-disable */
/* global WebImporter */

/**
 * Transformer: WKND Trendsetters site-wide DOM cleanup.
 *
 * All selectors are taken from the captured DOM in migration-work/cleaned.html
 * (FAQ page sample for https://wknd-trendsetters.pages.dev/faq). They apply
 * site-wide because the removed chrome (navbar, footer, skip link, base64
 * inline icons, Astro build artifacts) is generated by the site shell and
 * appears on every template.
 *
 * Removed content is all non-authorable (site chrome, build-tool artifacts,
 * decorative inline icons). No authorable page content is affected.
 */

const TransformHook = {
  beforeTransform: 'beforeTransform',
  afterTransform: 'afterTransform',
};

export default function transform(hookName, element, payload) {
  if (hookName === TransformHook.beforeTransform) {
    // Remove site chrome early so it cannot interfere with block parsing.
    // Selectors validated against migration-work/cleaned.html:
    //   line 1:  <a href="#main-content" class="skip-link">Skip to main content</a>
    //   line 1:  <div class="navbar"> ... </div>
    //   line 47: <button class="nav-mobile-menu-button" id="nav-toggle"> ... </button>
    //   line 60: <footer class="footer inverse-footer"> ... </footer>
    WebImporter.DOMUtils.remove(element, [
      'a.skip-link',
      '.navbar',
      '#nav-toggle',
      '.nav-mobile-menu-button',
      'footer.footer',
      'footer.inverse-footer',
    ]);

    // Remove all base64 inline data-URI SVG icons. These decorate nav carets,
    // mobile menu toggle, mega-menu icons, FAQ expand icons, footer social
    // icons, logo marks, etc. They are not authorable content and are noise
    // when authoring in a document.
    // Validated: <img src="data:image/svg+xml;base64,..."> occurs on lines 1,
    // 2, 6, 10, 14, 18, 22, 26, 30, 34, 37, 47, 48, 49, 50, 60 of cleaned.html.
    element.querySelectorAll('img[src^="data:image/svg+xml;base64,"]').forEach((img) => {
      img.remove();
    });
  }

  if (hookName === TransformHook.afterTransform) {
    // Defense-in-depth: ensure any leftover site chrome, plus elements that
    // shouldn't reach the output, are removed after block parsing too.
    WebImporter.DOMUtils.remove(element, [
      'a.skip-link',
      '.navbar',
      '#nav-toggle',
      '.nav-mobile-menu-button',
      'footer.footer',
      'footer.inverse-footer',
      'iframe',
      'noscript',
      'link',
      'script',
      'style',
    ]);

    // Strip Astro build-time artifacts. Validated against cleaned.html:
    //   line 1:  <body data-astro-cid-37fxchfa="">
    //   lines 47-50 (and similar): <svg ... data-astro-cid-rbygaycu=""> on FAQ icons
    // These attributes are emitted by the Astro build tool for style scoping
    // and are not authorable metadata.
    element.querySelectorAll('*').forEach((el) => {
      [...el.attributes].forEach((attr) => {
        if (attr.name.startsWith('data-astro-cid-')) {
          el.removeAttribute(attr.name);
        }
      });
    });

    // Remove any residual empty <img> elements whose src was already stripped
    // elsewhere (defensive – the beforeTransform pass removes the base64
    // icons; this catches anything added by a parser that left an empty img).
    element.querySelectorAll('img').forEach((img) => {
      const src = img.getAttribute('src') || '';
      if (src.startsWith('data:image/svg+xml;base64,')) {
        img.remove();
      }
    });
  }
}
